const proxyOperation = `-- name: ProxyOperation :one
SELECT o.id, o.proxy_id, o.project_id, o.route_id, o.generation, o.idempotency_key, o.request_hash, o.state, o.snapshot, o.snapshot_hash, o.plan, o.plan_hash, o.run_id, o.created_by, o.created_at, o.updated_at,EXISTS(SELECT 1 FROM hosting_proxies p WHERE p.hold_operation_id=o.id) AS mutation_hold,
EXISTS(SELECT 1 FROM hosting_proxy_restore_holds h WHERE h.proxy_id=o.proxy_id) AS restore_held,
(SELECT jsonb_build_object('id',receipt_id,'body_hash',body_hash,'created_at',created_at) FROM hosting_proxy_receipts WHERE operation_id=o.id AND phase='prepared') AS prepared_receipt,
(SELECT body FROM hosting_proxy_receipts WHERE operation_id=o.id AND phase='prepared') AS prepared,
(SELECT jsonb_build_object('id',receipt_id,'body_hash',body_hash,'created_at',created_at) FROM hosting_proxy_receipts WHERE operation_id=o.id AND phase='complete') AS complete_receipt,
(SELECT body FROM hosting_proxy_receipts WHERE operation_id=o.id AND phase='complete') AS result
 ,EXISTS(SELECT 1 FROM audit_events WHERE target_id=o.id AND action='hosting.route_switch_metadata_conflict') AS metadata_conflict
FROM hosting_proxy_operations o WHERE o.id=$1
`

type ProxyOperationRow struct {
	ID               string          `json:"id"`
	ProxyID          string          `json:"proxy_id"`
	ProjectID        *string         `json:"project_id"`
	RouteID          *string         `json:"route_id"`
	Generation       int64           `json:"generation"`
	IdempotencyKey   string          `json:"idempotency_key"`
	RequestHash      string          `json:"request_hash"`
	State            string          `json:"state"`
	Snapshot         json.RawMessage `json:"snapshot"`
	SnapshotHash     string          `json:"snapshot_hash"`
	Plan             []byte          `json:"plan"`
	PlanHash         *string         `json:"plan_hash"`
	RunID            *string         `json:"run_id"`
	CreatedBy        string          `json:"created_by"`
	CreatedAt        time.Time       `json:"created_at"`
	UpdatedAt        time.Time       `json:"updated_at"`
	MutationHold     bool            `json:"mutation_hold"`
	RestoreHeld      bool            `json:"restore_held"`
	PreparedReceipt  json.RawMessage `json:"prepared_receipt"`
	Prepared         json.RawMessage `json:"prepared"`
	CompleteReceipt  json.RawMessage `json:"complete_receipt"`
	Result           json.RawMessage `json:"result"`
	MetadataConflict bool            `json:"metadata_conflict"`
}

func (q *Queries) ProxyOperation(ctx context.Context, id string) (ProxyOperationRow, error) {
	row := q.db.QueryRow(ctx, proxyOperation, id)
	var i ProxyOperationRow
	err := row.Scan(
		&i.ID,
		&i.ProxyID,
		&i.ProjectID,
		&i.RouteID,
		&i.Generation,
		&i.IdempotencyKey,
		&i.RequestHash,
		&i.State,
		&i.Snapshot,
		&i.SnapshotHash,
		&i.Plan,
		&i.PlanHash,
		&i.RunID,
		&i.CreatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.MutationHold,
		&i.RestoreHeld,
		&i.PreparedReceipt,
		&i.Prepared,
		&i.CompleteReceipt,
		&i.Result,
		&i.MetadataConflict,
	)
	return i, err
}

